import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000007;
    static boolean[] visitedNodes = new boolean[MAX_SIZE];
    static final long MODULUS = 1000000007;
    static long[] divisorFreq = new long[MAX_SIZE];
    static long[] cycleSizes = new long[MAX_SIZE];
    static long[] dynamicProg = new long[MAX_SIZE];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long totalResult = 1;

        int pValue = scanner.nextInt();
        int kValue = scanner.nextInt();

        for (int i = 0; i < pValue; i++) {
            if (!visitedNodes[i]) {
                int size = 0;
                long current = i;
                while (!visitedNodes[(int) current]) {
                    visitedNodes[(int) current] = true;
                    current = (kValue * current) % pValue;
                    size++;
                }
                cycleSizes[size]++;
            }
        }

        for (int i = 1; i <= pValue; i++) {
            dynamicProg[i] = (cycleSizes[i] * i) % MODULUS;
        }

        for (int i = 1; i <= pValue; i++) {
            divisorFreq[i] = (divisorFreq[i] + dynamicProg[i]) % MODULUS;
            for (int j = i + i; j <= pValue; j += i) {
                divisorFreq[j] = (dynamicProg[i] + divisorFreq[j]) % MODULUS;
            }
        }

        for (int i = 1; i <= pValue; i++) {
            if (i == 1) {
                for (int j = 0; j < cycleSizes[i] - 1; j++) {
                    totalResult = (totalResult * cycleSizes[i]) % MODULUS;
                }
            } else {
                for (int j = 0; j < cycleSizes[i]; j++) {
                    totalResult = (totalResult * divisorFreq[i]) % MODULUS;
                }
            }
        }

        if (kValue == 1) {
            totalResult = (totalResult * divisorFreq[1]) % MODULUS;
        }

        System.out.println(totalResult);
        scanner.close();
    }
}
